import React, { useEffect, useState } from "react";
import UserProfileCard from "./UserProfileCard";
import AchievementsPanel from "./AchievementsPanel";
import "./dashboard.css";
const API = process.env.REACT_APP_API || "http://localhost:4000";

function StatCard({ value, label }) {
  return (
    <div className="stat-card">
      <div className="stat-value">{value ?? "—"}</div>
      <div className="stat-label">{label}</div>
    </div>
  );
}

export default function AdminDashboard({ token, setMsg, reports }) {
  const [admin, setAdmin] = useState(null);
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);
  const [loading, setLoading] = useState({ profile: false, data: false });

  // fetch profile on mount / when token changes
  useEffect(() => {
    if (!token) return;
    (async () => {
      setLoading((s) => ({ ...s, profile: true }));
      try {
        const res = await fetch(`${API}/api/auth/me`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json?.message || "Failed to load profile");
        setAdmin(json.user || null);
      } catch (err) {
        console.error(err);
        setMsg(err.message || "Error loading profile");
      } finally {
        setLoading((s) => ({ ...s, profile: false }));
      }
    })();
  }, [token, setMsg]);

  // common loader helper
  const loadData = async (endpoint, setter, field = null, errMsg = "Failed to load") => {
    if (!token) return setMsg("Login as admin first");
    setLoading((s) => ({ ...s, data: true }));
    // clear only the target setter (so other UI can remain)
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.message || errMsg);
      setter(field ? json[field] || [] : json);
      setMsg(""); // clear messages on success
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    } finally {
      setLoading((s) => ({ ...s, data: false }));
    }
  };

  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");
    setLoading((s) => ({ ...s, data: true }));
    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.message || "Failed to load most active");
      setMostActive(json.top || null);
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    } finally {
      setLoading((s) => ({ ...s, data: false }));
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;
    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.message || "Failed to delete NGO");
      setNgos((prev) => prev?.filter((n) => n.id !== id) || []);
      setMsg("NGO removed successfully");
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to delete NGO");
    }
  };

  // easy UI data for top cards (keeps compatibility with your reports prop)
  const donationsSum = reports?.donations
    ? reports.donations.reduce((s, d) => s + parseFloat(d.amount || 0), 0)
    : "-";

  return (
    <div className="dashboard-wrap">
      <div className="dashboard-container">

        {/* Header */}
        <div className="dashboard-header">
          <h1>Admin Dashboard</h1>
          {/* Profile sits under the title, left aligned */}
        </div>

        {/* Top grid: left achievements, center profile, right quick */}
        <div className="top-grid">
          <div className="left-col">
            <AchievementsPanel token={token} me={{ points: reports?.adminPoints || 0 }} setMsg={setMsg} />
          </div>

          <div className="center-col">
            <div className="profile-box">
              {loading.profile ? (
                <div className="loading">Loading profile…</div>
              ) : (
                <UserProfileCard data={admin} />
              )}
            </div>

            {/* Summary stats under profile */}
            <div className="profile-stats">
              <div className="points-bar">
                <div className="points-value">{reports?.adminPoints ?? 0}</div>
                <div className="points-label">Total Points</div>
              </div>

              <div className="mini-stats">
                <StatCard value={reports?.totalUsers || (admin && admin.totalUsers) || 0} label="Total Users" />
                <StatCard value={reports?.totalEvents || 0} label="Total Events" />
                <StatCard value={reports?.volunteers?.length || 0} label="Volunteers" />
              </div>
            </div>
          </div>

          <div className="right-col">
            <div className="card quick-actions">
              <h4>Quick Actions</h4>
              <div className="btn-stack">
                <button onClick={() => loadData("/api/actions/top-volunteers", setEventStats, "top", "Failed to load top volunteers")}>
                  Top Volunteer
                </button>
                <button onClick={() => loadData("/api/actions/top-donors", setEventStats, "top", "Failed to load top donors")}>
                  Top Donor
                </button>
                <button onClick={() => loadData("/api/actions/badges", setEventStats, "badges", "Failed to load badges")}>
                  View Badges
                </button>
              </div>
            </div>

            <div className="card most-active">
              <h4>Most Active NGO</h4>
              <button className="full" onClick={loadMostActive}>Load Most Active NGO</button>
              {mostActive && (
                <div className="most-active-info">
                  <strong>{mostActive.name}</strong>
                  <div className="muted">Activity Score: {mostActive.activity_score}</div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Admin Reports row */}
        <section className="reports-section">
          <h3>Admin Reports</h3>
          <div className="reports-cards">
            <StatCard value={donationsSum} label="Total Donation Amount (₹)" />
            <StatCard value={reports?.volunteers?.length || 0} label="Total Volunteers" />
            <StatCard value={reports?.feedbacks?.length || 0} label="Feedbacks" />
          </div>

          <div className="action-buttons">
            <button onClick={() => loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")}>View NGOs</button>
            <button onClick={() => loadData("/api/actions/registered-events", setEvents, "events", "Failed to load events")}>View Events</button>
            <button onClick={() => loadData("/api/actions/event-stats", setEventStats, "events", "Failed to load stats")}>View Stats</button>
          </div>
        </section>

        {/* Dynamic data section (only one type displayed but stacked vertically for clarity) */}
        <section className="dynamic-section">
          {events && (
            <>
              <h4>Registered Events</h4>
              <div className="list-grid">
                {events.length ? events.map((e) => (
                  <div key={e.id} className="list-item">
                    <div className="list-title">{e.title}</div>
                    <div className="muted small">{e.date}</div>
                  </div>
                )) : <div className="muted">No events registered.</div>}
              </div>
            </>
          )}

          {eventStats && (
            <>
              <h4>Event Statistics</h4>
              <div className="list-grid">
                {eventStats.length ? eventStats.map((ev) => (
                  <div key={ev.id} className="list-item horizontal">
                    <img src={ev.image_url || "/placeholder-120x80.png"} alt="" className="thumb" />
                    <div>
                      <div className="list-title">{ev.title}</div>
                      <div className="muted small">Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}</div>
                    </div>
                  </div>
                )) : <div className="muted">No event statistics loaded.</div>}
              </div>
            </>
          )}

          {ngos && (
            <>
              <h4>Registered NGOs</h4>
              <div className="list-grid">
                {ngos.length ? ngos.map((n) => (
                  <div key={n.id} className="list-item spaced">
                    <div>
                      <div className="list-title">{n.name}</div>
                      <div className="muted small">{n.email}</div>
                    </div>
                    <div>
                      <button className="danger" onClick={() => deleteNgo(n.id)}>Remove</button>
                    </div>
                  </div>
                )) : <div className="muted">No NGOs registered.</div>}
              </div>
            </>
          )}

          {/* generic top lists (top donors/vols/badges) */}
          {eventStats && eventStats.length && eventStats[0].name && (
            <>
              <h4>Top List</h4>
              <div className="list-grid">
                {eventStats.map((t, i) => (
                  <div key={i} className="list-item">
                    <div className="list-title">{t.name}</div>
                    <div className="muted small">{t.detail || ""}</div>
                  </div>
                ))}
              </div>
            </>
          )}

        </section>
      </div>
    </div>
  );
}
